<template>
  <view class="container">
    <!-- 返回按钮 -->
    <view class="back-button" @click="goBack">
      <text class="back-text">← 返回菜单</text>
    </view>
    
    <!-- AI对战模式标识 -->
    <view class="ai-mode-banner">
      <view class="ai-icon">🤖</view>
      <text class="ai-text">AI对战模式</text>
    </view>
    
    <!-- AI玩家状态 -->
    <view class="ai-players-section">
      <h3>AI玩家状态</h3>
      <view class="ai-players-container">
        <view class="ai-player" v-for="(ai, index) in aiPlayers" :key="index">
          <view class="ai-avatar">🤖</view>
          <view class="ai-info">
            <text class="ai-name">{{ ai.name }}</text>
            <text class="ai-cards">手牌: {{ ai.cards }}张</text>
            <text class="ai-status" :class="{ 'ai-thinking': ai.isThinking }">
              {{ ai.isThinking ? '思考中...' : '等待中' }}
            </text>
          </view>
        </view>
      </view>
    </view>
    
    <!-- 游戏控制按钮 -->
    <view class="control-section">
      <button @click="SynInformation" :disabled="!canbutton">同步信息</button>
      <button @click="startAIGame" :disabled="!canbutton">开始AI对战</button>
      <button @click="restartAIGame" :disabled="gameStatus !== 'playing'">重新开始</button>
    </view>
    
    <!-- 出牌权显示 -->
    <view class="turn-section" v-if="gameStatus === 'playing' && currentPlayer">
      <view :class="['turn-indicator', isYourTurn ? 'your-turn' : 'other-turn']">
        <text v-if="isYourTurn" class="turn-text">🎮 轮到您出牌</text>
        <text v-else-if="isAIPlayerTurn" class="turn-text">🤖 轮到AI玩家 {{ currentPlayer }} 出牌</text>
        <text v-else class="turn-text">⏳ 轮到玩家 {{ currentPlayer }} 出牌</text>
      </view>
    </view>
    
    <!-- 牌堆显示 - 只在有牌时显示 -->
    <view class="piles-section" v-if="gamePiles">
      <h3>牌堆</h3>
      <view class="piles-container">
        <view v-for="(pile, suit) in gamePiles" :key="suit">
          <!-- 只在有牌时显示牌堆 -->
          <view v-if="pile.cards && pile.cards.length > 0" class="pile-item">
            <view class="pile">
              <!-- 牌堆标题 - 显示花色和牌数 -->
              <view class="pile-header">
                <text class="pile-suit">{{ getSuitSymbol(suit) }}</text>
                <text class="pile-count">{{ pile.count }}张</text>
              </view>
              
              <!-- 牌堆序列 - 横向展开，每张牌完整显示 -->
              <view class="pile-cards">
                <view class="pile-sequence">
                  <view 
                    v-for="(entry, index) in pile.cards" 
                    :key="index"
                    :class="['pile-card', 'card-' + entry.card.suit, entry.card.rank === '7' ? 'seven-card' : '']"
                    :style="{ marginLeft: index > 0 ? '-20px' : '0' }"
                  >
                    <text class="card-rank">{{ entry.card.rank }}</text>
                    <text class="card-suit">{{ getSuitSymbol(entry.card.suit) }}</text>
                  </view>
                </view>
              </view>
              
              <text v-if="pile.playedBy" class="pile-player">
                最后出牌: {{ pile.playedBy }}
              </text>
            </view>
          </view>
        </view>
      </view>
    </view>
    
    <!-- 玩家列表 -->
    <view class="player-section">
      <h3>游戏玩家 ({{ playerlist.length }})</h3>
      <ul>
        <li v-for="(item, index) in playerlist" :key="index">
          玩家{{ index+1 }}: {{ item.deviceId || item }}
        </li>
      </ul>
    </view>
    
    <!-- 玩家手牌 -->
    <view class="cards-section" v-if="playerCards.length > 0">
      <h3>你的手牌 ({{ playerCards.length }}张)</h3>
      
      <!-- 选中的牌 -->
      <view class="selected-section" v-if="selectedCard">
        <h4>已选牌</h4>
        <view class="selected-cards">
          <view class="card-item">
            <view :class="['card', 'card-' + selectedCard.suit, 'selected']">
              <text class="card-rank">{{ selectedCard.rank }}</text>
              <text class="card-suit">{{ getSuitSymbol(selectedCard.suit) }}</text>
            </view>
          </view>
        </view>
        <view class="action-buttons">
          <button @click="playCard" class="play-btn">出牌</button>
          <button @click="clearSelection" class="clear-btn">取消选择</button>
        </view>
        
        <!-- Pass按钮 -->
        <view class="pass-section" v-if="isYourTurn && gameStatus === 'playing'">
          <button @click="passTurn" class="pass-btn" :disabled="!canPass">
            Pass
          </button>
          <text v-if="!canPass" class="pass-hint">
            {{ passHint }}
          </text>
        </view>
      </view>
      
      <!-- 所有手牌 -->
      <view class="cards-container">
        <view v-for="(card, index) in playerCards" :key="index" class="card-item">
          <view 
            :class="['card', 'card-' + card.suit, selectedCard && selectedCard.id === card.id ? 'selected' : '']"
            @click="selectCard(card)"
          >
            <text class="card-rank">{{ card.rank }}</text>
            <text class="card-suit">{{ getSuitSymbol(card.suit) }}</text>
            <text v-if="selectedCard && selectedCard.id === card.id" class="selected-mark">✓</text>
          </view>
        </view>
      </view>
    </view>
    
    <!-- AI对战统计 -->
    <view class="stats-section" v-if="gameStatus === 'playing'">
      <h3>对战统计</h3>
      <view class="stats-container">
        <view class="stat-item">
          <text class="stat-label">游戏回合</text>
          <text class="stat-value">{{ gameRounds }}</text>
        </view>
        <view class="stat-item">
          <text class="stat-label">AI出牌次数</text>
          <text class="stat-value">{{ aiPlayCount }}</text>
        </view>
        <view class="stat-item">
          <text class="stat-label">剩余AI玩家</text>
          <text class="stat-value">{{ remainingAIPlayers }}</text>
        </view>
      </view>
    </view>
    
  </view>
</template>

<script>
const app = getApp();
export default {
  
	data(){
		return{
			canbutton : false,
			isConnected : false ,
			playerlist:[],
			playerCards: [],
			selectedCard: null, // 选中的单张牌
			gameStatus: 'waiting', // waiting, playing, ended
			gamePiles: {
				hearts: { suit: 'hearts', count: 0, topCard: null, playedBy: null, cards: [] },
				spades: { suit: 'spades', count: 0, topCard: null, playedBy: null, cards: [] },
				diamonds: { suit: 'diamonds', count: 0, topCard: null, playedBy: null, cards: [] },
				clubs: { suit: 'clubs', count: 0, topCard: null, playedBy: null, cards: [] }
			},
			currentPlayer: null, // 当前出牌玩家
			isYourTurn: false, // 是否轮到当前玩家出牌
			canPass: false, // 是否可以pass
			passHint: '', // pass提示信息
      
      // AI对战特有数据
      aiPlayers: [
        { name: 'AI玩家1', cards: 0, isThinking: false },
        { name: 'AI玩家2', cards: 0, isThinking: false }
      ],
      isAIPlayerTurn: false, // 是否是AI玩家回合
      gameRounds: 0, // 游戏回合数
      aiPlayCount: 0, // AI出牌次数
      remainingAIPlayers: 2 // 剩余AI玩家数量
		}
	},
  onLoad(){
    this.checkWebSocketConnection();
    this.setupWebSocketListener();
  },
  methods: {
    // 返回菜单
    goBack() {
      uni.navigateBack();
    },
    
    // 检查WebSocket连接状态
    checkWebSocketConnection() {
      if (!app.globalData.ws || app.globalData.ws.readyState !== WebSocket.OPEN) {
        uni.showModal({
          title: '连接错误',
          content: 'WebSocket未连接，请先连接服务器',
          showCancel: false,
          success: () => {
            uni.navigateBack();
          }
        });
        return false;
      }
      this.canbutton = true;
      this.isConnected = true;
      return true;
    },
    
    // 设置WebSocket监听器
    setupWebSocketListener() {
      if (app.globalData.ws) {
        app.globalData.ws.onMessage((res) => {
          this.handleWebSocketMessage(res);
        });
        
        // 监听连接关闭
        app.globalData.ws.onClose(() => {
          this.canbutton = false;
          this.isConnected = false;
          uni.showToast({
            title: '连接已断开',
            icon: 'error'
          });
        });
      }
    },
    
    // 处理WebSocket消息
    handleWebSocketMessage(res) {
      try {
        const data = JSON.parse(res.data);
        console.log('收到WebSocket消息:', data);
        
        switch(data.type) {
          case 'playerList':
            this.playerlist = data.players;
            break;
            
          case 'gameStartRes':
            this.gameStatus = 'playing';
            this.playerCards = data.content.playerCards || [];
            this.currentPlayer = data.content.currentPlayer;
            this.isYourTurn = data.content.currentPlayer === app.globalData.deviceId;
            this.isAIPlayerTurn = data.content.isAIGame && data.content.currentPlayer.includes('ai_player');
            this.updateAIPlayers(data.content);
            
            // 隐藏loading
            uni.hideLoading();
            uni.showToast({
              title: 'AI对战开始！',
              icon: 'success'
            });
            break;
            
          case 'cardPlayed':
            this.handleCardPlayed(data.content);
            break;
            
          case 'aiPlayCard':
            this.handleAIPlayCard(data.content);
            break;
            
          case 'passSuccess':
            this.handlePassSuccess(data.content);
            break;
            
          case 'gamePiles':
            this.gamePiles = data.content || data.piles;
            break;
            
          case 'playerCards':
            this.playerCards = data.cards || data.content;
            break;
            
          case 'aiPlayerUpdate':
            this.updateAIPlayerStatus(data.content);
            break;
            
          case 'gameEnd':
            this.gameStatus = 'ended';
            uni.showModal({
              title: '游戏结束',
              content: data.message || data.content || '游戏已结束',
              showCancel: false
            });
            break;
            
          case 'alert':
            uni.showToast({
              title: data.content,
              icon: 'none'
            });
            break;
        }
      } catch (error) {
        console.error('处理WebSocket消息错误:', error);
      }
    },
    
    // 更新AI玩家状态
    updateAIPlayers(data) {
      if (data.aiPlayers) {
        this.aiPlayers = data.aiPlayers.map((aiId, index) => ({
          name: `AI玩家${index + 1}`,
          cards: 0, // 初始为0，后续通过消息更新
          isThinking: false
        }));
        this.remainingAIPlayers = this.aiPlayers.length;
      }
    },
    
    // 处理AI出牌
    handleAIPlayCard(data) {
      if (data && data.aiPlayer && data.card) {
        // 更新牌堆信息
        if (data.pileInfo) {
          this.gamePiles = data.pileInfo;
        }
        
        // 更新当前玩家
        this.currentPlayer = data.currentPlayer;
        this.isYourTurn = data.currentPlayer === app.globalData.deviceId;
        this.isAIPlayerTurn = data.currentPlayer.includes('ai_player');
        
        // 增加AI出牌计数
        this.aiPlayCount++;
        this.gameRounds++;
        
        // 显示AI出牌提示
        uni.showToast({
          title: `AI玩家出牌: ${data.card.rank}${this.getSuitSymbol(data.card.suit)}`,
          icon: 'none',
          duration: 2000
        });
      }
    },
    
    // 处理Pass成功
    handlePassSuccess(data) {
      if (data && data.nextPlayer) {
        this.currentPlayer = data.nextPlayer;
        this.isYourTurn = data.nextPlayer === app.globalData.deviceId;
        this.isAIPlayerTurn = data.nextPlayer.includes('ai_player');
        this.gameRounds++;
        
        uni.showToast({
          title: data.message || 'Pass成功',
          icon: 'success'
        });
      }
    },
    
    // 更新单个AI玩家状态
    updateAIPlayerStatus(data) {
      const aiIndex = data.aiIndex;
      if (aiIndex >= 0 && aiIndex < this.aiPlayers.length) {
        this.aiPlayers[aiIndex] = {
          ...this.aiPlayers[aiIndex],
          cards: data.cards || this.aiPlayers[aiIndex].cards,
          isThinking: data.isThinking || false
        };
        this.remainingAIPlayers = this.aiPlayers.filter(ai => ai.cards > 0).length;
        
        if (data.isThinking) {
          this.aiPlayCount++;
        }
      }
    },
    
    // 处理出牌
    handleCardPlayed(data) {
      if (data.pile) {
        const suit = data.pile.suit;
        if (this.gamePiles[suit]) {
          this.gamePiles[suit] = {
            ...this.gamePiles[suit],
            count: data.pile.count,
            topCard: data.pile.topCard,
            playedBy: data.pile.playedBy,
            cards: data.pile.cards || []
          };
        }
      }
      
      // 更新当前玩家
      if (data.currentPlayer) {
        this.currentPlayer = data.currentPlayer;
        this.isYourTurn = data.currentPlayer === app.globalData.deviceId;
        this.isAIPlayerTurn = data.currentPlayer.includes('ai_player');
      }
      
      // 如果是AI出牌，增加计数
      if (data.player && data.player.includes('ai_player')) {
        this.aiPlayCount++;
      }
      
      this.gameRounds++;
    },
    
    // 同步信息
    SynInformation() {
      if (!this.checkWebSocketConnection()) {
        return;
      }
      
      try {
        app.globalData.ws.send(JSON.stringify({
          type: 'getPlayerList'
        }));
      } catch (error) {
        uni.showToast({
          title: '同步失败',
          icon: 'error'
        });
        console.error('同步信息失败:', error);
      }
    },
    
    // 开始AI对战
    startAIGame() {
      if (!this.checkWebSocketConnection()) {
        return;
      }
      
      uni.showLoading({
        title: '启动AI对战...'
      });
      
      try {
        // 发送AI对战请求，包含玩家ID
        app.globalData.ws.send(JSON.stringify({
          type: 'startAIGame',
          playerid: app.globalData.deviceId
        }));
        
        // 5秒后隐藏loading，防止卡死
        setTimeout(() => {
          uni.hideLoading();
        }, 5000);
      } catch (error) {
        uni.hideLoading();
        uni.showToast({
          title: '发送失败',
          icon: 'error'
        });
        console.error('发送AI对战请求失败:', error);
      }
    },
    
    // 重新开始AI对战
    restartAIGame() {
      if (!this.checkWebSocketConnection()) {
        return;
      }
      
      uni.showLoading({
        title: '重新开始...'
      });
      
      try {
        // 发送重新开始请求
        app.globalData.ws.send(JSON.stringify({
          type: 'startAIGame',
          playerid: app.globalData.deviceId
        }));
        
        setTimeout(() => {
          uni.hideLoading();
        }, 5000);
      } catch (error) {
        uni.hideLoading();
        uni.showToast({
          title: '重新开始失败',
          icon: 'error'
        });
        console.error('重新开始失败:', error);
      }
    },
    
    // 选择牌
    selectCard(card) {
      this.selectedCard = card;
    },
    
    // 清除选择
    clearSelection() {
      this.selectedCard = null;
    },
    
    // 出牌
    playCard() {
      if (!this.selectedCard || !this.isYourTurn) return;
      
      if (!this.checkWebSocketConnection()) {
        return;
      }
      
      try {
        app.globalData.ws.send(JSON.stringify({
          type: 'playCard',
          card: this.selectedCard
        }));
        this.selectedCard = null;
      } catch (error) {
        uni.showToast({
          title: '出牌失败',
          icon: 'error'
        });
        console.error('出牌失败:', error);
      }
    },
    
    // Pass
    passTurn() {
      if (!this.isYourTurn || !this.canPass) return;
      
      if (!this.checkWebSocketConnection()) {
        return;
      }
      
      try {
        app.globalData.ws.send(JSON.stringify({
          type: 'passTurn'
        }));
      } catch (error) {
        uni.showToast({
          title: 'Pass失败',
          icon: 'error'
        });
        console.error('Pass失败:', error);
      }
    },
    
    // 获取花色符号
    getSuitSymbol(suit) {
      const symbols = {
        hearts: '♥',
        spades: '♠',
        diamonds: '♦',
        clubs: '♣'
      };
      return symbols[suit] || suit;
    }
  }
}
</script>

